+
+    private final Notification sentNotification = new Notification("Message sent");
+    private final Dialog leaveDialog = new Dialog();
+    private ContinueNavigationAction pendingNavigation;
+
+    public ContactView(MessageStore store) {
+        this.store = store;
+
+        H1 heading = new H1("Contact");
+        RouterLink aboutLink = new RouterLink("About", AboutView.class);
+
+        FormLayout form = new FormLayout();
+        form.add(nameField, emailField, phoneField, messageField);
+        form.setMaxWidth("40rem");
+
+        messageField.setMaxRows(8);
+        nameField.addValueChangeListener(e -> sendButton.setEnabled(true));
+        emailField.addValueChangeListener(e -> sendButton.setEnabled(true));
+        phoneField.addValueChangeListener(e -> sendButton.setEnabled(true));
+        messageField.addValueChangeListener(e -> sendButton.setEnabled(true));
+        nameField.setValueChangeMode(ValueChangeMode.EAGER);
+        emailField.setValueChangeMode(ValueChangeMode.EAGER);
+        phoneField.setValueChangeMode(ValueChangeMode.EAGER);
+        messageField.setValueChangeMode(ValueChangeMode.EAGER);
+
+        // Enter sends, as the Send button does
+        Shortcuts.addShortcutListener(form, this::sendIfEnabled, Key.ENTER);
+
+        sendButton.addClickListener(e -> send());
+
+        grid.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        grid.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        grid.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.setItems(store.newestFirst());
+
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.add(new Paragraph("You have typed something that has not been sent yet. "
+                + "If you leave now, it will be lost."));
+        Button keepEditing = new Button("Keep editing", e -> closeLeaveDialog());
+        Button discard = new Button("Discard", e -> {
+            ContinueNavigationAction navigation = pendingNavigation;
+            pendingNavigation = null;
+            leaveDialog.close();
+            if (navigation != null) {
+                navigation.proceed();
+            }
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        leaveDialog.getFooter().add(keepEditing, discard);
+        add(leaveDialog, sentNotification);
+
+        setPadding(true);
+        add(heading, aboutLink, form, sendButton, grid);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasTypedInput()) {
+            return;
+        }
+        pendingNavigation = event.postpone();
+        leaveDialog.open();
+    }
+
+    private void closeLeaveDialog() {
+        pendingNavigation = null;
+        leaveDialog.close();
+    }
+
+    private boolean hasTypedInput() {
+        return !nameField.getValue().isEmpty()
+                || !emailField.getValue().isEmpty()
+                || !phoneField.getValue().isEmpty()
+                || !messageField.getValue().isEmpty();
+    }
+
+    private void sendIfEnabled() {
+        if (sendButton.isEnabled()) {
+            send();
+        }
+    }
+
+    private void send() {
+        clearErrors();
+        if (!validate()) {
+            return;
+        }
+
+        store.add(new ContactMessage(
+                nameField.getValue().trim(),
+                emailField.getValue().trim(),
+                phoneField.getValue().trim(),
+                messageField.getValue().trim()));
+        grid.setItems(store.newestFirst());
+
+        sentNotification.open();
+
+        // Clearing the fields re-enables Send through the listeners, so disable it last
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+        sendButton.setEnabled(false);
+    }
+
+    private boolean validate() {
+        boolean valid = true;
+
+        String name = nameField.getValue().trim();
+        String email = emailField.getValue().trim();
+        String phone = phoneField.getValue().trim();
+        String message = messageField.getValue();
+
+        if (name.isEmpty()) {
+            markInvalid(nameField, "Name is required");
+            valid = false;
+        }
+
+        if (!email.isEmpty() && !EMAIL.matcher(email).matches()) {
+            markInvalid(emailField, "Enter a valid e-mail address");
+            valid = false;
+        } else if (email.isEmpty() && phone.isEmpty()) {
+            markInvalid(emailField, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (message.isBlank()) {
+            markInvalid(messageField, "Message is required");
+            valid = false;
+        } else if (message.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(messageField, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private static void markInvalid(HasValidation field, String error) {
+        field.setInvalid(true);
+        field.setErrorMessage(error);
+    }
+
+    private void clearErrors() {
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        phoneField.setInvalid(false);
+        messageField.setInvalid(false);
+    }
+}
